23	/**
24	 * Base class for testing the interactive installer.
25	 */
26	abstract class InstallerTestBase extends BrowserTestBase {
27	
28	  use RequirementsPageTrait;
29	
30	  /**
31	   * Custom settings.php values to write for a test run.
32	   *
33	   * @var array
34	   *   An array of settings to write out, in the format expected by
35	   *   SettingsEditor::rewrite().
36	   *
37	   * @see \Drupal\Core\Site\SettingsEditor::rewrite()
38	   */
39	  protected $settings = [];
40	
41	  /**
42	   * The language code in which to install Drupal.
43	   *
44	   * @var string
45	   */
46	  protected $langcode = 'en';
47	
48	  /**
49	   * The installation profile to install.
50	   *
51	   * @var string
52	   */
53	  protected $profile = 'testing';
54	
55	  /**
56	   * Additional parameters to use for installer screens.
57	   *
58	   * @var array
59	   *
60	   * @see FunctionalTestSetupTrait::installParameters()
61	   */
62	  protected $parameters = [];
63	
64	  /**
65	   * A string translation map used for translated installer screens.
66	   *
67	   * Keys are English strings, values are translated strings.
68	   *
69	   * @var array
70	   */
71	  protected $translations = [
72	    'Save and continue' => 'Save and continue',
73	  ];
74	
75	  /**
76	   * Whether the installer has completed.
77	   *
78	   * @var bool
79	   */
80	  protected $isInstalled = FALSE;
81	
82	  /**
83	   * {@inheritdoc}
84	   */
85	  protected function installParameters() {
86	    $params = parent::installParameters();
87	    // Set the checkbox values to FALSE so that
88	    // \Drupal\Tests\BrowserTestBase::translatePostValues() does not remove
89	    // them.
90	    $params['forms']['install_configure_form']['enable_update_status_module'] = FALSE;
91	    $params['forms']['install_configure_form']['enable_update_status_emails'] = FALSE;
92	    return $params;
93	  }
94	
95	  /**
96	   * We are testing the installer, so set up a minimal environment for that.
97	   */
98	  public function installDrupal() {
99	    // Define information about the user 1 account.
100	    $this->rootUser = new UserSession([
101	      'uid' => 1,
102	      'name' => 'admin',
103	      'mail' => 'admin@example.com',
104	      'pass_raw' => $this->randomMachineName(),
105	    ]);
106	
107	    // If any $settings are defined for this test, copy and prepare an actual
108	    // settings.php, so as to resemble a regular installation.
109	    if (!empty($this->settings)) {
110	      // Not using File API; a potential error must trigger a PHP warning.
111	      copy(DRUPAL_ROOT . '/sites/default/default.settings.php', DRUPAL_ROOT . '/' . $this->siteDirectory . '/settings.php');
112	      $this->writeSettings($this->settings);
113	    }
114	
115	    // Note that FunctionalTestSetupTrait::installParameters() returns form
116	    // input values suitable for a programmed
117	    // \Drupal::formBuilder()->submitForm().
118	    // @see InstallerTestBase::translatePostValues()
119	    $this->parameters = $this->installParameters();
120	
121	    // Set up a minimal container (required by BrowserTestBase). Set cookie and
122	    // server information so that XDebug works.
123	    // @see install_begin_request()
124	    $request = Request::create($GLOBALS['base_url'] . '/core/install.php', 'GET', [], $_COOKIE, [], $_SERVER);
125	    $request->setSession(new Session(new MockArraySessionStorage()));
126	    $this->container = new ContainerBuilder();
127	    $request_stack = new RequestStack();
128	    $request_stack->push($request);
129	    $this->container
130	      ->set('request_stack', $request_stack);
131	    $this->container
132	      ->setParameter('language.default_values', Language::$defaultValues);
133	    $this->container
134	      ->register('language.default', 'Drupal\Core\Language\LanguageDefault')
135	      ->addArgument('%language.default_values%');
136	    $this->container
137	      ->register('string_translation', 'Drupal\Core\StringTranslation\TranslationManager')
138	      ->addArgument(new Reference('language.default'));
139	    $this->container
140	      ->register('http_client', 'GuzzleHttp\Client')
141	      ->setFactory('http_client_factory:fromOptions');
142	    $this->container
143	      ->register('http_client_factory', 'Drupal\Core\Http\ClientFactory')
144	      ->setArguments([new Reference('http_handler_stack')]);
145	    $handler_stack = HandlerStack::create();
146	    $test_http_client_middleware = new TestHttpClientMiddleware();
147	    $handler_stack->push($test_http_client_middleware(), 'test.http_client.middleware');
148	    $this->container
149	      ->set('http_handler_stack', $handler_stack);
